/* Story and Free Play share PPSim transactions, calendar, and independent v3 saves. */
window.PPSimGame=(()=>{
 const E=PPSim,W=PPSimWorld,A=PPSimActivities,$=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),m=E.money;
 const scope=new URLSearchParams(window.location.search).get('reviewSession'),prefix='paycheckPanic.financial.v3.'+(scope?scope+'.':''),indexKey=prefix+'index',selectedKey=prefix+'selected';
 let S=null,revision=0,paused=false,toastTimer,modalBack=null,setup={mode:'story',profile:'independent',char:'alex'},lastFocus=null;
 const state=()=>S,key=()=>prefix+'campaign.'+S.id;
 function save(){if(!S||!E.valid(S)){$('saveStatus').textContent='Save blocked: invalid state';return false;}try{const existing=JSON.parse(localStorage.getItem(key())||'null');if(existing&&existing.revision>revision){$('saveStatus').textContent='Newer save in another tab';return false;}const envelope={schema:3,rules:E.VERSION,revision:revision+1,savedAt:new Date().toISOString(),state:S};if(existing)localStorage.setItem(key()+'.backup',JSON.stringify(existing));localStorage.setItem(key(),JSON.stringify(envelope));revision++;try{localStorage.setItem(selectedKey,S.id);const list=JSON.parse(localStorage.getItem(indexKey)||'[]').filter(c=>c.id!==S.id);list.unshift({id:S.id,profile:S.profile,mode:S.mode,month:S.month,completed:S.completed,updated:envelope.savedAt});localStorage.setItem(indexKey,JSON.stringify(list));$('saveStatus').textContent='Saved';}catch(e){$('saveStatus').textContent='Campaign saved; backup recommended';}return true;}catch(e){$('saveStatus').textContent='Save failed — download a backup';return false;}}
 function commit(fn){const before=structuredClone(S);try{const result=fn(S);if(result?.ok===false){S=before;W.state=S;toast(result.error||'That action is not available.');return false;}if(!save())throw Error('The change was not saved. Download a backup or load the newer save.');hud();return true;}catch(e){S=before;W.state=S;toast(e.message||'The action could not be saved.');return false;}}
 function load(id){try{let e=JSON.parse(localStorage.getItem(prefix+'campaign.'+id)||'null');if(!e||!E.valid(e.state))e=JSON.parse(localStorage.getItem(prefix+'campaign.'+id+'.backup')||'null');if(!e||!E.valid(e.state))throw Error();S=e.state;revision=Number.isSafeInteger(e.revision)&&e.revision>=0?e.revision:0;start();}catch(e){toast('That campaign could not be loaded. Its stored data is preserved.');}}
 function close(){W.clear();$('modalWrap').hidden=true;$('modal').replaceChildren();modalBack=null;if(lastFocus?.isConnected)lastFocus.focus();}
 function modal(title,body,buttons=[],back=close){W.clear();A.suspend();lastFocus=document.activeElement;$('modalWrap').hidden=false;modalBack=back;$('modal').innerHTML=`<h2 id="modalTitle">${esc(title)}</h2>${body}<div class="actions"></div><div class="backRow"></div>`;const actions=$('modal').querySelector('.actions');for(const b of buttons){const el=document.createElement('button');el.textContent=b.text;el.disabled=!!b.disabled;if(b.testid)el.dataset.testid=b.testid;el.onclick=b.fn;actions.append(el);}if(back){const b=document.createElement('button');b.textContent='Back';b.onclick=back;$('modal').querySelector('.backRow').append(b);}$('modal').focus();}
 function toast(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4200);}
 function measure(){document.documentElement.style.setProperty('--hud-h',$('hud').hidden?'0px':$('hud').offsetHeight+'px');document.documentElement.style.setProperty('--tools-h',$('toolbar').offsetHeight+'px');}
 new ResizeObserver(measure).observe($('hud'));new ResizeObserver(measure).observe($('toolbar'));addEventListener('resize',measure);
 function hud(){if(!S)return;const f=E.forecast(S),next=E.missing(S)[0],item=(label,value)=>`<div class="statusItem"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`;$('financialStatus').innerHTML=item(S.mode==='story'?'Chapter '+Math.min(6,S.month)+'/6':'Free Play · month '+S.month,'Day '+S.day+'/30')+item('Cash',m(S.cash))+item('Available before payday',m(f.available))+item('Debt',m(S.card+(S.loan?.balance||0)+S.unpaid.reduce((n,b)=>n+b.amount,0)))+item('Next payday','Day '+f.nextPay+' · '+m(f.pay))+item('Goal',m(S.goal)+' / $1,200');$('hud').dataset.testid='financial-hud';$('wellbeingStatus').textContent=`Emergency ${m(S.emergency)} · Investments ${m(S.investment)} · ${S.blocks}/4 time blocks · Energy ${Math.round(S.energy)} · Happiness ${Math.round(S.happiness)} · Stress ${Math.round(S.stress)}`;
 const last=[...S.ledger].reverse().find(t=>Object.values(t.delta).some(v=>v!==0)||Object.keys(t.stats||{}).length||t.unpaid)||S.ledger.at(-1);$('receipt').textContent=last?`${last.label}: ${Object.entries(last.delta).map(([k,v])=>`${k} ${m(last.before[k])} → ${m(last.before[k]+v)}`).join(' · ')||(last.category==='activity'?'Score saved; finances unchanged':'Cash unchanged')}${Object.entries(last.liability||{}).map(([k,v])=>' · '+k+' '+m(v[0])+' → '+m(v[1])).join('')}${Object.entries(last.stats||{}).map(([k,v])=>' · '+k+' '+Math.round(v[0])+' → '+Math.round(v[1])+(last.statExpected?.[k]!=null&&Math.abs(v[1]-v[0])<Math.abs(last.statExpected[k])?' (capped)':'')).join('')}${last.unpaid?' · unpaid '+m(last.unpaid):''}`:'Your cash includes money for upcoming commitments.';
 $('objective').textContent=S.completed?'Story complete — review your financial journey':S.mode==='free'?'Free Play · choose your own goal; Plan & calendar advances time':next?`${E.chapters[S.month-1].title} · ${next[1]} →`:S.day<30?'Chapter decisions complete · advance to the month-end review →':'Review and revise your month →';$('objective').hidden=false;
 $('soundButton').textContent=S.settings.muted?'Sound off':'Sound on';$('soundButton').setAttribute('aria-pressed',String(S.settings.muted));$('motionButton').textContent=S.settings.reduced?'Reduced motion':'Motion on';$('motionButton').setAttribute('aria-pressed',String(S.settings.reduced));document.body.classList.toggle('reduced',S.settings.reduced);measure();}
 function start(){paused=false;$('title').hidden=true;$('hud').hidden=$('toolbar').hidden=false;W.start(S,api);hud();if(S.activity)A.resume();else if(S.completed)finalReview();else chapterIntro(false);}
 function newGame(mode){setup={mode,profile:'independent',char:'alex'};chooseScenario();}
 function chooseScenario(){modal(setup.mode==='story'?'Choose your story':'Start Free Play',`<p>Both situations use the same town and financial rules. Appearance does not affect income or luck.</p><div class="twoColumn">${Object.entries(E.profiles).map(([id,p])=>`<div class="choice"><h3>${esc(p.name)}</h3><p>${esc(p.intro)}</p><p>${m(p.wage)}/hour · ${p.hours} scheduled hours/month · opening cash ${m(p.cash)}</p><button data-profile="${id}" aria-pressed="${setup.profile===id}">${setup.profile===id?'Selected':'Choose this situation'}</button></div>`).join('')}</div><h3>Your character</h3><div class="charChoices">${['alex','maya','jay','sam','classic'].map(id=>`<button data-char="${id}" aria-pressed="${setup.char===id}">${id[0].toUpperCase()+id.slice(1)}</button>`).join('')}</div>`,[{text:'Begin '+(setup.mode==='story'?'story':'Free Play'),testid:'begin-campaign',fn:()=>{S=E.initial(setup.profile,setup.mode,crypto.getRandomValues(new Uint32Array(1))[0]);S.id=crypto.randomUUID();S.char=setup.char;revision=0;if(save())start();}}],()=>{$('title').hidden=false;close();});$('modal').querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{setup.profile=b.dataset.profile;chooseScenario();});$('modal').querySelectorAll('[data-char]').forEach(b=>b.onclick=()=>{setup.char=b.dataset.char;chooseScenario();});}
 function chapterIntro(force=true){const ch=E.chapters[Math.min(5,S.month-1)];if(!force&&S.introMonth===S.month){close();return;}S.introMonth=S.month;save();modal(S.mode==='story'?`Chapter ${S.month}: ${ch.title}`:'Your open-town financial life',`<p><b>${esc(ch.npc)}</b></p><p>${esc(S.mode==='story'?ch.opening:E.profiles[S.profile].intro)}</p><div class="notice">${S.month===1?'Move with arrows, WASD, the touch stick, or click a clear path. E enters nearby doors and opens room choices. Walking and reading do not advance financial time.':S.month===4?'Scheduled hours are 20% lower this month. That change is already in the pay forecast.':S.month===6?'Food prices in this fictional basket rise 5% this month. Revisit your plan.':'Your earlier contracts, debt, and decisions carry forward.'}</div><p>Two scheduled paydays: days 15 and 30. Bills have their own dates. You have four discretionary blocks for extra work, learning, preparation, and leisure.</p>`,[{text:'Walk into town',fn:close},{text:'Review plan and calendar',fn:calendar}],null);}
 function help(){modal('How this financial life works',`<p><b>Your goal:</b> Manage six months, make the chapter decisions, and explain how you revised your plan. The ${esc(E.profiles[S?.profile||'independent'].goal.toLowerCase())} targets $1,200. Debt or a missed goal does not erase your learning.</p><p><b>Controls:</b> arrows/WASD or touch stick; E or the nearby action button. Click an open floor space to walk. Locations sets a walking route. F2 shows feet, solid footprints, reach zones, and NPC paths.</p><p><b>Time and work:</b> Plan & calendar advances to a bill or payday. Scheduled hours create pay, with deductions. Practice scores do not change agreed wages. A real extra shift uses a time block and adds hours to the month’s pay.</p><p><b>Budget:</b> cash is not all available to spend. The forecast protects bills due before payday, overdue bills, meal coverage, and remaining savings allocations. Saving a plan does not automatically transfer money.</p><p><b>Consequences:</b> fees, interest, repayments, contract terms, and lost time carry forward. Revise spending, use reserves, explore extra work, or discuss a supplied repayment arrangement. Leisure is a legitimate choice with a cost.</p><p><b>Fictional cases:</b> these prices, contracts, investment paths, and simplified Alberta payroll examples teach comparisons. They are not personal quotes or guaranteed returns. No real financial information is requested.</p><p><a href="https://curriculum.learnalberta.ca/curriculum/en/gfc/CALM/PEW0770" target="_blank" rel="noopener">Draft CALM financial literacy</a> · <a href="https://www.canada.ca/en/financial-consumer-agency/services/make-budget.html" target="_blank" rel="noopener">FCAC budgeting guidance</a></p>`,[],S?close:()=>{$('title').hidden=false;close();});}
 function advance(){if(S.day===30){monthReview();return;}const before=S.ledger.length;if(commit(s=>E.advance(s))){const newRows=S.ledger.slice(before);modal(`Day ${S.day}: ${S.day===15||S.day===30?'payday':'commitments'}`,`<p>${S.day===15||S.day===30?'Scheduled hours have been paid. Check the stub at Work or the Bank.':'These obligations were scheduled in your case.'}</p>${table(newRows.map(t=>[t.label,m(t.due??Math.abs(t.delta.cash||0)),m(t.paid??Math.abs(t.delta.cash||0)),t.unpaid?'Unpaid '+m(t.unpaid):'Recorded']),['Transaction','Amount','Paid / received','Result'])}${S.unpaid.length?'<div class="notice warning">There are unpaid obligations. Review your cash-flow plan and recovery options.</div>':''}`, [{text:'Back to town',fn:close},{text:'View plan and calendar',fn:calendar}],null);}}
 function table(rows,headers){return `<table class="rows"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
 function calendar(){const f=E.forecast(S),rows=E.bills(S).map(b=>['Day '+b.day,b.name,m(b.amount),b.day<=S.day?'Settled or recorded':'Upcoming']);if(S.statement)rows.push(['Day 25','Card statement minimum',m(E.minimum(S.statement)),'Interest continues on unpaid balance']);if(S.loan)rows.push(['Day 25','Loan payment',m(S.loan.payment),S.loan.variable?'Variable rate':'Fixed rate']);modal('Plan & calendar',`<p>${S.mode==='story'?'Chapter '+S.month+'/6':'Free Play month '+S.month} · day ${S.day}/30 · ${S.blocks} discretionary time blocks remain.</p><div class="document"><h3>Before payday on day ${f.nextPay}</h3>${table([['Cash now',m(S.cash)],['Upcoming obligations',m(f.due)],['Overdue bills',m(f.arrears)],['Unbought meal basket allowance',m(f.food)],['Planned savings still reserved',m(f.reserved)],['Available for another choice',m(f.available)],['Projected next net pay',m(f.pay)]],['Item','Amount'])}</div>${table(rows,['Due date','Commitment','Amount','Status'])}<p>Available is a forecast. It does not include emergency savings, your goal account, or investment value.</p>`,[{text:'Edit cash-flow plan',fn:budget},{text:'View transactions',fn:ledger},{text:S.day===30?'Review this month':'Advance to next scheduled date',testid:'story-next',fn:advance},{text:'Chapter decisions and routes',fn:objectives}],close);}
 function ledger(){const rows=S.ledger.slice(-80).reverse().map(t=>[`M${t.month} D${t.day}`,t.label,Object.entries(t.delta).map(([k,v])=>k+' '+(v>=0?'+':'')+m(v)).join(' · '),t.unpaid?'Unpaid '+m(t.unpaid):t.interest?'Interest '+m(t.interest):'']);modal('Your transaction record',table(rows,['Date','What happened','Account changes','Details']),[{text:'Download financial journey',fn:downloadReport}],calendar);}
 function objectives(){const tasks=E.tasks(S);modal(S.mode==='story'?'This chapter’s decisions':'Optional financial investigations',`<ul class="taskList">${tasks.map(([k,label,place])=>`<li>${E.marked(S,k)?'✓ ':''}${esc(label)} <button data-route="${place}">Walk there</button></li>`).join('')}</ul><p>Steps complete when you perform the action. Opening a menu alone does not complete it.</p>`,[{text:'Review this month',fn:monthReview}],close);$('modal').querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{const id=b.dataset.route;close();if(id==='town')return;W.navigate(id);});}
 function budget(){const f=E.forecast(S),plan=S.budgetDraft||S.budgets[S.month]||{food:E.foodQuote(S).cost,leisure:8000,goal:20000,emergency:10000,debt:E.minimum(S.statement)+(S.loan?.payment||0)};modal('Your cash-flow plan',`<p>Expected monthly net pay ${m(f.monthNet)}. Fixed commitments ${m(f.monthlyBills)}. Plan from take-home money; a low payment can still mean a large total cost.</p><form id="budgetForm" data-testid="plan-form"><div class="twoColumn">${[['food','Food'],['leisure','Leisure and social plans'],['goal','Goal savings'],['emergency','Emergency savings'],['debt','Debt payments']].map(([k,label])=>`<label class="field">${label}<input type="number" min="0" step="0.01" name="${k}" value="${(plan[k]/100).toFixed(2)}"></label>`).join('')}</div></form><p id="budgetResult"></p><p class="compact">A savings allocation is a plan. Use Transfers to move money. Exceeding a category shows an overage; it does not secretly block your purchase.</p>`,[{text:'Save plan',testid:'save-plan',fn:()=>{const p=readBudget();if(commit(s=>({ok:E.saveBudget(s,p)}))) {toast('Cash-flow plan saved.');budget();}}},{text:'Back to bank',testid:'budget-back',fn:bank},{text:'Leave bank',fn:close}],null);function result(){const p=readBudget(),sum=Object.values(p).reduce((n,v)=>n+v,0)+f.monthlyBills,gap=f.monthNet-sum;$('budgetResult').textContent=`Planned total ${m(sum)}. ${gap>=0?m(gap)+' unallocated':m(-gap)+' above expected income'}.`;if(Object.values(p).every(n=>Number.isSafeInteger(n)&&n>=0)){S.budgetDraft=p;save();}}$('budgetForm').oninput=result;result();}
 function readBudget(){return Object.fromEntries(['food','leisure','goal','emergency','debt'].map(k=>[k,Math.round(Number($('budgetForm').elements[k].value)*100)]));}
 function purchase(kind,arg={},after=close,reasonKey=null,reasonText='',activityKind=null){const q=E.quote(S,kind,arg);if(!q.ok){toast(q.error);return;}const recurring=kind==='contract'&&arg.choice==='term'?'Adds $25/month for 24 months, total $600. Cancellation requires paying the remaining device balance.':kind==='bike'?'Replaces the transit pass with a $10/month maintenance reserve.':kind==='loan'?`Borrowed ${m(q.amount)}. APR ${arg.variable?'12%, changing to 15% in chapter four':'10% fixed'}; initial monthly payment ${m(E.loanPayment(q.amount,arg.variable?.12:.10,12))}, 12-month starting amortization, no origination fee, $25 missed-payment fee.`:kind==='training'?`Two time blocks and $120. The case wage rises $0.50/hour next month: ${m(E.profiles[S.profile].hours*50)}/normal month.`:'';modal('Confirm your choice',`<p><b>${esc(q.label)}</b></p>${table([['Cost now',m(q.cost)],['Cash',m(S.cash)+' → '+m(q.after)],['Time blocks',S.blocks+' → '+(S.blocks-q.blocks)],['Available before payday after choice',m(q.available)]],['Effect','Value'])}${recurring?`<p>${recurring}</p>`:''}${q.warning?`<div class="notice warning">${esc(q.warning)} Review the forecast before committing.</div>`:''}${kind==='food'?`<p>Complete 30-day simulation meal coverage. Total household basket ${m(q.total)}; household support ${m(q.support)}. Preparation uses ${q.blocks} time block(s).</p>`:''}`, [{text:'Confirm '+q.label,fn:()=>{const id=crypto.randomUUID();if(activityKind){A.begin(activityKind,false,{id,kind,arg});return;}if(commit(s=>{const r=E.apply(s,id,kind,arg);if(r.ok&&reasonKey)E.reason(s,reasonKey,q.label,reasonText);return r;}))after();}},{text:'Review plan first',fn:calendar}],after);}
 function food(){const already=S.food?.month===S.month,choices=already?S.food.choices:S.foodDraft||[1,1,1,1];modal('FreshMart meal basket',`<p>${already?'Your paid basket covers this month.':'Choose packages for all four groups. Each option is a complete monthly quantity for this fictional case.'} Compare preparation time, convenience, and total cost.</p><form id="foodForm" data-testid="basket-form">${E.foodGroups.map((g,i)=>`<label class="field foodLine">${esc(g.name)}<canvas width="55" height="60" class="foodArt" data-art="${i}" aria-label="${esc(g.name)}"></canvas><select name="g${i}" ${already?'disabled':''}>${g.options.map((o,n)=>`<option value="${n}" ${choices[i]===n?'selected':''}>${esc(o.name)} — ${m(Math.round(o.cost*(S.month>=6?1.05:1)))}</option>`).join('')}</select><p class="compact">${esc(g.description)}</p></label>`).join('')}</form><p id="basketTotal"></p><div class="notice">Packages are monthly baskets, not calories or a nutrition assessment. Rice alone cannot replace the other meal groups. Real package prices are available in the unit-price comparison.</div>`,[{text:already?'Paid this month — view receipt':'Buy this month’s basket',disabled:already,fn:()=>purchase('food',{choices:readFood()},food)},{text:'Compare real package units',fn:unitPrices},{text:'Practice Checkout Chaos',fn:()=>practice('checkout')},{text:'Record a meal-coverage shortfall',disabled:already,fn:()=>decision('food','An unfilled meal plan','<p>This case has no complete meal coverage. At month end energy falls 10 and stress rises 5 before regular recovery. Explain the shortfall and the support or revision you will investigate. This does not purchase food or remove debt.</p>',[{text:'Record the shortfall and investigate support'}],food)}],()=>location('grocery'));$('foodForm').onchange=()=>{S.foodDraft=readFood();save();updateFood();};updateFood();$('modal').querySelectorAll('[data-art]').forEach(c=>{const g=E.foodGroups[c.dataset.art];PPArt.sprite(c.getContext('2d'),g.sheet,g.art,27,60,48,55);});function updateFood(){const q=E.foodQuote(S,readFood());$('basketTotal').textContent=`Household basket ${m(q.total)} · your share ${m(q.cost)} · ${q.blocks} preparation block(s) · 30 days covered.${S.month>=6?' Includes the case’s 5% price rise.':''}`;}}
 function readFood(){return [0,1,2,3].map(i=>Number($('foodForm').elements['g'+i].value));}
 function unitPrices(){modal('Package size changes the comparison',`<p>Two rice offers in this case: 2 kg for $9.62, or 500 g for $3.20. A smaller sticker does not always mean cheaper food.</p>${table([['2 kg rice','$9.62','$4.81/kg'],['500 g rice','$3.20','$6.40/kg'],['Eggs, 12','$4.95','$0.41 each'],['Milk, 2 L','$5.53','$2.77/L']],['Package','Price','Unit price'])}<p>These national reference prices come from the July 2026 <a href="https://www.statcan.gc.ca/en/topics-start/food-price?HPA=1" target="_blank" rel="noopener">Statistics Canada food-price hub</a>; the 500 g offer is fictional. Monthly baskets include quantities, variety, and other ingredients beyond these examples.</p>`,[{text:'Back to basket',fn:food}],()=>location('grocery'));}
 function decision(key,title,body,options,back=close){const done=E.marked(S,key),prior=S.decisions.find(d=>d.id===S.month+':'+key);if(done){modal(title,`<p>Your choice: <b>${esc(prior?.choice||'Completed')}</b></p><p>${esc(prior?.reason||'Recorded in the chapter evidence.')}</p><p>The result remains in your ledger and current plan.</p>`,[{text:'Review current plan',fn:calendar}],back);return;}modal(title,body+`<label class="field">One sentence: what matters in this choice?<textarea id="decisionReason" data-testid="decision-reason" maxlength="600" placeholder="Explain the cost, timing, goal, or tradeoff you considered."></textarea></label><p id="decisionError" class="error"></p>`,options.map(o=>({text:o.text,fn:()=>{const why=$('decisionReason').value.trim();if(S.mode==='story'&&why.length<8){$('decisionError').textContent='Add a brief reason before choosing.';return;}if(o.kind)purchase(o.kind,o.arg||{},back,key,why);else if(commit(s=>{if(o.effect)o.effect(s);E.reason(s,key,o.text,why);return{ok:true};}))back();}})),back);}
 function bank(){modal('Bank — your money and commitments',`<p>Cash ${m(S.cash)} · emergency savings ${m(S.emergency)} · goal ${m(S.goal)} · investments ${m(S.investment)}.</p><p>Borrowing is an obligation. A transfer between your own accounts does not create income.</p>`,[{text:'Cash-flow plan',fn:budget},{text:'Transfers and saving',fn:transfers},{text:'Debt and borrowing offers',fn:debt},{text:'Pay stubs',fn:paystubs},{text:'Saving and investment choices',fn:allocation},{text:'Future planning calculator',fn:futureLab},{text:'Explore a mortgage',fn:mortgage},{text:'Transaction record',fn:ledger}],close);}
 function transfers(){modal('Give each account a purpose',`<p>Emergency ${m(S.emergency)} · goal ${m(S.goal)} · card ${m(S.card)}. Emergency savings earn a fictional 3% nominal annual rate, applied monthly. No fee in this case.</p><label class="field">Amount ($)<input id="transferAmount" type="number" min="0.01" step="0.01" value="50"></label><div class="notice">Goal and emergency balances are separate from cash. Transfers appear in both account records and never count as earned income.</div>`,[{text:'Cash → emergency savings',fn:()=>purchase('emergency',{amount:amount('transferAmount')},transfers)},{text:'Cash → goal',fn:()=>purchase('goal',{amount:amount('transferAmount')},transfers)},{text:'Emergency savings → cash',fn:()=>purchase('withdraw',{amount:amount('transferAmount')},transfers)},{text:'Pay card principal',fn:()=>purchase('repay',{amount:amount('transferAmount')},transfers)},{text:'Pay overdue bills',fn:()=>purchase('arrears',{amount:amount('transferAmount')},transfers)}],bank);}
 function amount(id){return Math.round(Number($(id).value)*100);}
 function paystubs(){const p=S.stubs.at(-1);if(!p){modal('Pay stubs',`<p>Your first pay is scheduled for day 15. There is no collected stub yet.</p><p>${E.monthlyHours(S)} scheduled hours this month at ${m(E.wage(S))}/hour. Practice scores do not change that agreement.</p>`,[{text:'Open calendar',fn:calendar}],bank);return;}modal('Collected pay stub',`<div class="document"><h3>Town employer · Month ${p.month}, day ${p.day}</h3>${table([['Hours',p.hours,''],['Hourly rate',m(p.wage),''],['Gross pay',m(p.gross),m(p.ytd.gross)],['CPP',m(p.cpp),m(p.ytd.cpp)],['EI',m(p.ei),m(p.ytd.ei)],['Income tax withheld',m(p.tax),m(p.ytd.tax)],['Net pay deposited',m(p.net),m(p.ytd.net)]],['Item','This pay','Year to date'])}</div><p>The net pay is already deposited once. Current amounts differ from year-to-date totals.</p><label class="field">Which amount can fund your cash budget?<select id="stubAnswer"><option value="">Choose…</option><option value="gross">Gross pay</option><option value="net">Net pay</option><option value="ytd">Year-to-date gross</option></select></label><p id="stubFeedback"></p><p class="compact">Limited fictional payroll case: Alberta basic claims, 24 pay periods, CPP and EI, annualized income within the first brackets. Actual payroll depends on declarations, timing, and individual circumstances. <a href="https://www.canada.ca/en/revenue-agency/services/forms-publications/payroll/t4127-payroll-deductions-formulas.html" target="_blank" rel="noopener">CRA source</a>.</p>`,[{text:'Check pay-stub understanding',fn:()=>{if($('stubAnswer').value==='net'){commit(s=>{E.mark(s,'paystub');return{ok:true};});$('stubFeedback').textContent='Correct: net pay is the amount deposited. Gross minus deductions equals net. Opening the stub again does not pay twice.';}else $('stubFeedback').textContent='Use this pay period’s net pay. Gross is before deductions; YTD covers earlier periods too.';}}],bank);}
 function debt(){const L=S.loan;modal('Debt, terms, and repayment',`<p>Card balance ${m(S.card)} · statement minimum ${m(E.minimum(S.statement))} · paid toward this statement ${m(S.paidCard)}.</p><p>Card: $2,000 limit; 20.99% nominal annual interest, applied monthly to the closing balance; minimum smaller of balance or the greater of $25 and 2%; $25 missed-minimum fee. This supplied contract has no grace-period model.</p>${L?`<p>Loan balance ${m(L.balance)} · payment ${m(L.payment)} · APR ${(L.apr*100).toFixed(1)}% · missed payment partition ${m(L.arrears)}. Arrears are part of this balance, not a second debt.</p>`:''}${table([['Personal / vehicle loan','Purpose, amount, APR, fees, term, payment, security','A secured lender may have rights over collateral.'],['Credit line / cash advance','Variable rate, fees, access, minimums','Access to credit does not show repayment capacity.'],['Student borrowing / BNPL','Eligibility, payment dates, fees, conditions','“Pay later” still creates an obligation.'],['Mortgage','Income evidence, down payment, term, amortization, credit, prepayment','A co-borrower takes real repayment responsibility.']],['Product','What to investigate','Risk'])}`, [{text:'Compare and explore borrowing offers',fn:borrowing},{text:'Repay or use a reserve',fn:transfers},{text:'Compare debt strategies',fn:debtStrategy},{text:'Discuss a supplied repayment arrangement',fn:arrangement}],bank);}
 function borrowing(){const amountC=120000,fixed=E.schedule(amountC,.10,12),variable=E.schedule(amountC,.12,12);decision('borrowing','Two supplied borrowing offers',`<p>You need to investigate a $1,200 purchase. You may keep this as a comparison without taking a loan.</p>${table([['Fixed personal loan','10%','12 months',m(fixed.payment),m(fixed.total)],['Variable personal loan','12% initially','12 months',m(variable.payment),m(variable.total)]],['Offer','APR','Amortization','Payment','Total at unchanged rate'])}<p>No origination fee; $25 late-payment fee. Unsecured; no co-borrower in these two offers. The variable case changes to 15% from month four, keeping the payment and extending repayment if needed. This is a scenario change, not a rate prediction.</p><p>Ask about repayment capacity, application requirements, collateral, fees, prepayment, and alternatives. A longer schedule lowers the payment while usually raising total interest.</p>`,[{text:'Compare only — do not borrow'},{text:'Take $1,200 fixed loan',kind:'loan',arg:{amount:120000}},{text:'Take $600 fixed loan instead',kind:'loan',arg:{amount:60000}},{text:'Take $1,200 variable loan',kind:'loan',arg:{amount:120000,variable:true}}],debt);}
 function debtStrategy(){const example=E.schedule(100000,.2099,24),short=E.schedule(100000,.2099,12);decision('debtStrategy','When debt grows',`<p>Compare a fictional $1,000 balance repaid at constant payments. Your actual card balance is ${m(S.card)}.</p>${table([['12 months',m(short.payment),m(short.interest)],['24 months',m(example.payment),m(example.interest)]],['Repayment horizon','Monthly payment','Total interest'])}<p>Minimum payments, extra principal payments, high-interest-first allocation, and an emergency reserve address different needs. New borrowing can rearrange obligations without reducing what you owe. Gambling can lose the money needed for repayment.</p><p><a href="https://www.canada.ca/en/financial-consumer-agency/services/debt/paying-debt.html" target="_blank" rel="noopener">FCAC debt strategies</a> and qualified credit counselling can help compare options; check fees and service limits.</p>`,[{text:'Prioritize high-rate debt while covering essentials'},{text:'Keep a small reserve, then increase repayments'},{text:'Seek qualified support and review the whole plan'}],debt);}
 function arrangement(){const owed=S.unpaid.reduce((n,b)=>n+b.amount,0),half=Math.ceil(owed/2);if(!owed){modal('Plan before a shortfall','<p>There are no overdue non-loan bills. Contact a provider early to clarify arrangements; approval is not guaranteed.</p>',[],debt);return;}decision('arrangement','A supplied shortfall arrangement',`<p>The fictional provider offers to repay half now and defer the rest until next month. Existing fees remain. Total overdue ${m(owed)}, due now ${m(half)}. The liability remains in the forecast. This is a supplied agreement, not a promise about real providers.</p>`,[{text:'Pay half now and accept the supplied arrangement',effect:s=>{const r=E.apply(s,crypto.randomUUID(),'arrears',{amount:half});if(!r.ok)throw Error(r.error);for(const b of s.unpaid)b.arrangedUntil=s.month+1;}},{text:'Keep the current schedule and review spending'}],debt);}
 function allocation(){decision('allocation','What should this dollar do next?',`<p>Cash ${m(S.cash)}. Card ${m(S.card)}. Emergency ${m(S.emergency)}. Goal ${m(S.goal)}. Choose where a real $50 goes, or investigate before committing.</p><p>Emergency and near-term money need access. A market fund can lose value; this case charges 0.5% annual management cost, applied monthly. The market path is illustrative and includes losses. It has no guaranteed return.</p><p>An <b>account</b> is a container; a savings deposit, GIC, bond, mutual fund, or other investment is what it holds. TFSA, RRSP, FHSA, RESP, and non-registered accounts have different purposes and rules. Eligibility, contribution room, taxes, and access must be checked for the actual person.</p>`,[{text:'Put $50 into emergency savings',kind:'emergency',arg:{amount:5000}},{text:'Put $50 toward the near-term goal',kind:'goal',arg:{amount:5000}},{text:'Repay $50 of card debt',kind:'repay',arg:{amount:5000}},{text:'Invest $50 for a long-term goal',kind:'invest',arg:{amount:5000}},{text:'Keep cash accessible and investigate product fit'}],bank);}
 function futureLab(){modal('Test a future plan',`<p>A calculator computes supplied assumptions; it does not predict returns or approve a product. Adjust a fictional goal and compare purchasing power.</p><div class="twoColumn"><label class="field">Starting savings ($)<input id="futureStart" type="number" min="0" max="1000000" value="500"></label><label class="field">Monthly contribution ($)<input id="futureMonthly" type="number" min="0" max="10000" value="50"></label><label class="field">Years<select id="futureYears"><option>5</option><option>10</option><option>20</option></select></label><label class="field">Annual illustrative return (%)<input id="futureReturn" type="number" min="-20" max="20" value="5"></label><label class="field">Annual inflation (%)<input id="futureInflation" type="number" min="0" max="15" value="2"></label></div><div id="futureResult" class="document"></div><h3>Borrowing to invest magnifies exposure</h3><p>$1,000 of your money alone loses $400 after a 40% asset fall. Combine it with a $1,000 loan and the $2,000 asset falls to $1,200: only $200 remains after repaying principal, before $120 of annual loan interest. The debt remains due even if the investment falls.</p><h3>Match access, risk, and life stage</h3>${table([['Emergency deposit','Accessible, low volatility; inflation can erode purchasing power','Near-term unexpected expense'],['GIC / term deposit','Contracted return; access or early exit may be restricted','Known date, suitable lock-up'],['Bonds / funds','Value, issuer risk, fees, diversification, and access vary','Depends on holdings and horizon'],['Crypto / concentrated assets','Large volatility, uncertain value, possible loss','Only after evaluating loss capacity and knowledge']],['Product','What to compare','Fit'])}<p>Starting school, a new job, a home purchase, and retirement can change the plan. Government resources, institutions, and qualified advisers offer different support; ask whether an adviser charges a fee or receives product compensation.</p>`,[{text:'Record a future-plan decision',fn:()=>decision('future','Your future planning conclusion','<p>Which assumption or risk most affects the plan you tested? Compare nominal money with purchasing power, and a near-term need with a long-term product.</p>',[{text:'Protect near-term access; invest only longer-term money'},{text:'Revise contributions or the goal after inflation'},{text:'Avoid leverage beyond my loss capacity'}],bank)}],bank);function update(){const p=Math.round(Number($('futureStart').value)*100),mth=Math.round(Number($('futureMonthly').value)*100),years=Number($('futureYears').value),r=Number($('futureReturn').value)/100,inf=Number($('futureInflation').value)/100;if(![p,mth,years,r,inf].every(Number.isFinite)||p<0||mth<0||r<-.2||r>.2){$('futureResult').textContent='Use the supplied input ranges.';return;}const result=E.future(p,mth,years,r,inf);$('futureResult').innerHTML=table([['Contributed',m(result.contributed)],['Nominal model value',m(result.value)],['In today’s purchasing power',m(result.real)],['Assumptions','Month-end deposits; annual effective return minus 0.5% fee, converted monthly; constant inflation; no tax model.']],['Measure','Result']);}$('modal').querySelectorAll('input,select').forEach(el=>el.oninput=update);update();}
 function mortgage(){modal('A future mortgage case',`<p>This fictional household is considering a $300,000 property with a $60,000 down payment. Mortgage principal is $240,000. The term is five years; amortization is a separate full repayment horizon.</p><label class="field">Amortization<select id="mortgageYears"><option>25</option><option>20</option></select></label><label class="field">Nominal rate, compounded semi-annually (%)<input id="mortgageRate" type="number" min="0.1" max="20" step="0.1" value="5"></label><div id="mortgageResult" class="document"></div><p>Compare income confirmation, down payment, credit history, fees, prepayment rights, property taxes, insurance, maintenance, and possible renewal rates. A low payment is not total ownership cost. A variable rate or renewal can change payment or balance risk depending on the agreement.</p>`,[{text:'Record mortgage understanding',fn:()=>decision('mortgage','Term and amortization','<p>What would you check before accepting this mortgage? The calculator holds the rate constant across amortization solely for comparison; renewal after five years is uncertain.</p>',[{text:'Compare total cost and five-year renewal exposure'},{text:'Check affordability beyond the mortgage payment'},{text:'Compare shorter amortization and prepayment terms'}],bank)}],bank);function update(){const years=Number($('mortgageYears').value),apr=Number($('mortgageRate').value)/100;if(!Number.isFinite(apr)||apr<=0||apr>.2)return;const r=E.schedule(24000000,apr,years*12,'semiannual');$('mortgageResult').innerHTML=table([['Monthly payment',m(r.payment)],['Balance after five-year term',m(r.rows[59]?.balance||0)],['Total interest if rate stayed constant',m(r.interest)],['Monthly convention','(1 + nominal rate / 2)^(1/6) − 1; cent rounding per period']],['Measure','Result']);}$('mortgageYears').onchange=$('mortgageRate').oninput=update;update();}
 function location(id,examine=false){if(!S)return;if(S.activity){A.resume();return;}if(examine){examinePoint(id);return;}const screens={home,office:work,grocery:food,bank,school,gym,diner,mall,dealer,lucky};(screens[id]||calendar)();}
 function roomButtons(id,buttons){return [...buttons,{text:'Walk through the room',fn:close},{text:'Leave building',fn:()=>{close();if(W.room)W.leave();}}];}
 function home(){modal('Home · make the next month possible',`<p>${esc(E.profiles[S.profile].intro)}</p><p>Goal: ${esc(E.profiles[S.profile].goal)} · ${m(S.goal)} / $1,200. Emergency reserve ${m(S.emergency)}. ${S.souvenirs?.length?'On your shelf: '+esc(S.souvenirs.join(', ')):''}</p><p>Rest uses one discretionary block and restores up to 20 energy while reducing up to 10 stress.</p>`,roomButtons('home',[{text:'Rest and regroup',fn:()=>purchase('rest',{},home)},{text:'Revise after reduced hours',fn:recovery},{text:'Plan & calendar',fn:calendar},{text:'Savings and repayments',fn:transfers}]),close);}
 function work(){modal('Workplace · agreed hours, real pay',`<p>${E.monthlyHours(S)} scheduled hours this month at ${m(E.wage(S))}/hour. Estimated monthly take-home ${m(E.forecast(S).monthNet)}. Day 15 and day 30 paydays deposit agreed wages once.</p><p>Your employment agreement determines pay; a practice mistake does not remove worked hours. Extra work competes with preparation, training, and leisure.</p>`,roomButtons('office',[{text:'Check collected pay stub',fn:paystubs},{text:'Take an extra 8-hour shift',fn:()=>purchase('extra',{},work)},{text:'Practice Checkout Chaos',fn:()=>practice('checkout')},{text:'Practice Inbox Blitz',fn:()=>practice('inbox')},{text:'Training and career choices',fn:school},{text:'Protect information',fn:security},{text:'Investigate the urgent message',fn:fraud}]),close);}
 function school(){const normal=E.profiles[S.profile].hours,extra=normal*50;modal('Learning centre · invest time deliberately',`<p>A supplied workplace certificate costs $120 and two blocks. It increases this case’s hourly wage by $0.50 from next month: ${m(extra)} more gross in a normal month. Gross-pay payback is ${(12000/extra).toFixed(1)} normal months, before deductions; real credentials do not guarantee employment or a wage increase.</p><p>${S.trained?'Your certificate is complete. The new rate starts after the training month.':'Compare study, an extra shift, and time needed for meal preparation.'}</p><p>Withheld payroll tax is an estimate. Keep pay slips and income records; credits, deductions, and an annual tax return can change your final tax. Do not treat gross pay as spendable cash.</p>`,roomButtons('school',[{text:'Complete supplied certificate',disabled:S.trained,fn:()=>purchase('training',{},school)},{text:'Review pay and deductions',fn:paystubs},{text:'Compare goals and time',fn:calendar},{text:'Explore future plans',fn:futureLab}]),close);}
 function gym(){modal('Gym · one continuous circuit',`<p>One visit: $12 and one block. Monthly membership: $45; four visits would otherwise cost $48, but each visit still uses a block. You have ${S.blocks} block(s) left. ${S.used.membership===S.month?'This month’s admission is covered.':''}</p><p>The 60-second circuit advances through strength, jump rope, and balance. Strength: hold Space and release in green. Rope: tap Space on the beat. Balance: left/right to stay in green. Touch buttons are provided.</p><p>Each segment contributes up to one-third of 100. Under 40: beginning; 40–69: steady; 70–100: strong. Score awards no money or career skill. The visit gives up to 10 energy and reduces up to 5 stress.</p>`,roomButtons('gym',[{text:'Start 60-second circuit',testid:'gym-start',fn:()=>purchase('gym',{},gym,null,'','gym')},{text:'Buy this month’s membership',disabled:S.used.membership===S.month,fn:()=>purchase('membership',{},gym)},{text:'Water fountain and recovery',fn:()=>examinePoint('gym')}]),close);}
 function diner(){modal('Diner · food, friends, and priorities',`<p>The monthly meal basket covers your ordinary food plan. A diner meal is an additional convenience or social choice.</p><p>Meal $18: up to +20 energy, +8 happiness, −3 stress. Smaller meal $9: up to +12 energy, +8 happiness, −3 stress. Benefits stop at the stat limits.</p>`,roomButtons('diner',[{text:'Order meal · $18',testid:'diner-meal',fn:()=>purchase('meal',{},diner)},{text:'Order smaller meal · $9',fn:()=>purchase('meal',{small:true},diner)},{text:'Make a social plan',fn:social},{text:'Practice Tip Runner',fn:()=>practice('delivery')},{text:'Compare meals at home',fn:food}]),close);}
 function practice(kind){modal('Choose practice timing','<p>Practice is included in your existing job or learning access. No admission charge or wage bonus. Timed play gives a short challenge; untimed play offers the same financial outcome.</p>',[{text:'Start timed practice',fn:()=>A.begin(kind)},{text:'Start untimed practice',fn:()=>A.begin(kind,true)}],()=>location(S.position.room||'office'));}
 function mall(){modal('Mall & arcade · enjoy a choice you can afford',`<p>Arcade entry: $5 and one block for this month’s visit. Once admitted, try the cabinets again without another fee this month. Cabinet scores and souvenirs have no cash resale value.</p><p>${S.used.arcade===S.month?'Your visit is paid this month.':'Check what the entry leaves available before payday.'}</p>`,roomButtons('mall',[{text:S.used.arcade===S.month?'Choose a cabinet':'Enter arcade · $5',fn:()=>{if(S.used.arcade===S.month)arcade();else purchase('arcade',{},arcade);}},{text:'Compare the device offers',fn:contract},{text:'Investigate the store’s promotion',fn:consumer}]),close);}
 function arcade(){modal('Choose a cabinet','<p>Your visit is paid. Scores stay separate from savings, employment, and chapter evidence.</p>',[{text:'Rhythm Rush',fn:()=>A.begin('rhythm')},{text:'Lane Racer',fn:()=>A.begin('racer')},{text:'Claw Machine',fn:()=>A.begin('claw')},{text:'Prize Wheel',fn:()=>A.begin('wheel')},{text:'Token Trader',fn:()=>A.begin('trader')}],mall);}
 function dealer(){modal('Transport · compare the full commitment',`<p>Current plan: ${S.transport==='bike'?'owned bike, $10/month maintenance reserve':m(E.profiles[S.profile].transport)+'/month transit'}. Transport affects your cash flow without promising more income.</p><p>A car carries purchase or financing, insurance, fuel, maintenance, parking, and repair risks. A vehicle loan payment alone is an incomplete comparison.</p>`,roomButtons('dealer',[{text:'Choose a transport plan',fn:transport},{text:'Compare financing terms',fn:borrowing},{text:'Review transport costs',fn:()=>examinePoint('dealer')}]),close);}
 function contract(){decision('contract','The monthly sticker and the whole agreement',`<p>Compare these fictional offers for the same device. Your current device works. Your existing $45 phone service is month-to-month and can be ended after the current paid month. The 24-month device agreement adds $25 to that service and requires paying the remaining device balance on cancellation.</p><p>Advertising anchors attention on a small monthly price. Friends, urgency, habits, and beliefs about debt can influence the choice. In your reason, identify the influence and the full commitment.</p>${table([['Keep it','$0','$0','No new obligation'],['Refurbished, cash','$420 now','$420','Money leaves immediately'],['24-month agreement','$25/month','$600','Cancellation: remaining balance'],['Refurbished, credit','$420 on card','$420 + interest','20.99% APR; minimum and fee rules apply']],['Choice','Timing','Total','Conditions'])}<p>The instalment lasts beyond this six-month story. A card purchase creates debt without increasing income. Warranty: six months against faults; optional returns: unopened within 14 days. Supplied terms may differ from actual consumer rights.</p>`,[{text:'Keep the device I have',kind:'contract',arg:{choice:'keep'}},{text:'Buy refurbished with cash',kind:'contract',arg:{choice:'cash'}},{text:'Accept the 24-month agreement',kind:'contract',arg:{choice:'term'}},{text:'Buy refurbished with credit',effect:s=>{if(!E.cardPurchase(s,crypto.randomUUID(),42000,'Refurbished device on card'))throw Error('This exceeds the supplied card limit.');s.contract={kind:'card',start:s.month,total:42000};}}],mall);}
 function social(){decision('social','Money can support things you value',`<p>Meet a friend on a free walk, or spend $35 on a movie and food. Both use one block and give the same simulated happiness benefit. A free choice can still cost time; paying for leisure can be reasonable when it fits the plan.</p><p>Available before payday: ${m(E.forecast(S).available)}. Preparation, extra work, and training need the same limited blocks.</p>`,[{text:'Choose the walk',kind:'social',arg:{choice:'free'}},{text:'Choose movie and food',kind:'social',arg:{choice:'paid'}}],diner);}
 function transport(){const p=E.profiles[S.profile],months=35000/(p.transport-1000);decision('transport','Choose travel that fits the case',`${table([['Transit',m(p.transport)+'/month','No purchase; continue paying the pass'],['Used bike + lock','$350 now + $10/month','Weather, route, maintenance, storage matter'],['Illustrative car','$250 payment + $180 insurance + $160 fuel + $80 repairs/month','Plus purchase, parking, and other fees']],['Option','Supplied cash costs','What else to consider'])}<p>Bike cash-cost break-even against transit: ${months.toFixed(1)} months, ignoring other costs and resale. Buying a bike after this month’s transit bill does not refund the pass. Your decision must fit the actual route and loss capacity.</p>`,[{text:'Keep transit and avoid the upfront cost'},{text:'Buy the supplied used bike',kind:'bike'},{text:'Keep transit while investigating future vehicle costs'}],dealer);}
 function recovery(){decision('recovery','Reduced hours: revise rather than wish',`<p>Normal hours ${E.profiles[S.profile].hours}; this month ${E.monthlyHours(S)}. Projected net pay ${m(E.forecast(S).monthNet)}, fixed commitments ${m(E.forecast(S).monthlyBills)}. Overdue bills ${m(S.unpaid.reduce((n,b)=>n+b.amount,0))}.</p><p>A recovery plan can reduce convenience and leisure, use a reserve, increase hours if feasible, or contact a provider. Borrowing and minimum payments move obligations into the future.</p>`,[{text:'Protect essentials and revise discretionary spending'},{text:'Use part of the reserve and rebuild it later'},{text:'Compare feasible extra work and provider support'}],()=>modal('Make the recovery plan concrete','<p>Your reason is saved. Use these actions to make its cash flow real.</p>',[{text:'Edit budget',fn:budget},{text:'Use reserve / repay bills',fn:transfers},{text:'Explore an extra shift',fn:work},{text:'Discuss an arrangement',fn:arrangement}],home));}
 function security(){decision('security','A public profile exposes more than you intended',`<p>This case’s fictional profile shows an address, birthday, school, and a public post about a new payroll account. An urgent message refers to those details. No real data or credentials are requested. Check sender domains, links, permissions, privacy settings, and independent sources before responding; keep devices updated and learn how to recover access.</p><p>Unique passwords, a password manager, multi-factor authentication, device updates, limited sharing, and account alerts reduce different risks. They cannot guarantee that no fraud occurs.</p>`,[{text:'Limit public details; use unique credentials and MFA',effect:s=>s.security={exposure:'limited',alerts:true}},{text:'Enable alerts and verify contacts independently',effect:s=>s.security={exposure:'reviewed',alerts:true}},{text:'Review sharing, updates, and recovery information',effect:s=>s.security={exposure:'reviewed',alerts:false}}],work);}
 function fraud(){decision('fraud','Urgent payroll message: verify the claim',`<div class=document><p>“Your pay is frozen. We know your school and address. Send a $75 verification fee and your password within 20 minutes.”</p></div><p>The request uses publicly exposed details, urgency, a fee, and credentials. A familiar detail is not proof of identity. Your selected security controls: ${esc(S.security?.exposure||'not yet reviewed')}.</p><p>If information was shared: contact the institution through a known channel, secure credentials, preserve evidence, and report suspected fraud to appropriate authorities. Reporting does not guarantee a refund.</p><p>This is credential phishing combined with an advance-fee payroll impersonation. Compare investment scams promising guaranteed profits, purchase scams involving nonexistent goods, and romance scams using a relationship to request money. The common claim is not evidence.</p><p>Known-channel payroll and the financial institution address the account. Local police and the <a href='https://antifraudcentre-centreantifraude.ca/' target=_blank rel=noopener>Canadian Anti-Fraud Centre</a> receive fraud reports; investment concerns can go to the <a href='https://www.asc.ca/' target=_blank rel=noopener>Alberta Securities Commission</a>. Verify contact details independently.</p>`,[{text:'Verify with payroll through a known contact; do not pay',effect:s=>s.fraud={response:'verified',loss:0}},{text:'Preserve evidence, secure the account, and report',effect:s=>s.fraud={response:'reported',loss:0}},{text:'Pay the requested fee despite the warning',kind:'scam'}],work);}
 function consumer(){decision('consumer','The advertised price is not the checkout total',`<p>A supplied shop promotion advertises a $30 accessory; checkout adds a previously undisclosed $12 mandatory fee. A “guaranteed investment return” banner sits beside it.</p>${table([['Accessory advertised','$30'],['Mandatory fee','$12'],['Checkout total','$42'],['Supplied voluntary return window','14 days unopened; keep receipt']],['Information','Terms'])}<p>Investigate product fit, advertising, fees, warranties, receipts, and applicable consumer protection. Ask the seller to explain or correct the terms; preserve evidence and use the relevant complaint channel. Neither a refund nor a remedy is guaranteed.</p><p><a href='https://www.alberta.ca/consumer-protection' target=_blank rel=noopener>Alberta consumer protection</a> · <a href='https://www.alberta.ca/file-consumer-complaint' target=_blank rel=noopener>Complaint information</a></p>`,[{text:'Decline and compare total prices elsewhere'},{text:'Ask for clear terms and keep evidence for a complaint'},{text:'Buy after acknowledging the $42 total',kind:'accessory'}],mall);}
 function examinePoint(id){const f=E.forecast(S),spent=cat=>S.ledger.filter(t=>t.month===S.month&&t.category===cat).reduce((n,t)=>n-(t.delta.cash||0),0),content={home:['Recovery at home',`Rest restores up to 20 energy and reduces up to 10 stress, costing one block. Energy now ${Math.round(S.energy)}, stress ${Math.round(S.stress)}. Emergency savings ${m(S.emergency)}.`,()=>purchase('rest',{},home)],office:['What is a promotion worth?',`The supplied certificate adds $0.50/hour next month. Normal gross gain ${m(E.profiles[S.profile].hours*50)}/month before deductions, for $120 and two blocks. Current rate ${m(E.wage(S))}/hour.`,school],grocery:['Read the package, not just the sticker',`The monthly home-cooking basket costs ${m(E.foodQuote(S).cost)} for your share. Different package sizes have different unit prices.`,unitPrices],bank:['Every dollar already has a claim',`Cash ${m(S.cash)}, commitments before payday ${m(f.due)}, overdue ${m(f.arrears)}, food allowance ${m(f.food)}, savings reserved ${m(f.reserved)}. Available ${m(f.available)}.`,budget],school:['Training has an opportunity cost',`The certificate uses two of your ${S.blocks} remaining blocks. One extra eight-hour shift adds ${m(E.wage(S)*8)} gross. Meal preparation uses blocks too; the wage increase starts next month.`,school],gym:['Water fountain · recover once this month',`Free water gives up to +3 energy and −2 stress once each month. Current energy ${Math.round(S.energy)}, stress ${Math.round(S.stress)}. Resets next month. ${S.used.fountain===S.month?'Already used this month.':''}`,()=>{if(S.used.fountain===S.month){toast('Next refill benefit resets next month.');return;}commit(s=>{const before={energy:s.energy,stress:s.stress};s.energy=Math.min(100,s.energy+3);s.stress=Math.max(0,s.stress-2);s.used.fountain=s.month;E.record(s,'fountain:'+s.month,'Water fountain',{},'wellbeing',{stats:{energy:[before.energy,s.energy],stress:[before.stress,s.stress]},statExpected:{energy:3,stress:-2}});return{ok:true};});examinePoint('gym');}],diner:['Convenience fits some plans',`Meals cost $9 or $18; the home basket costs ${m(E.foodQuote(S).cost)} for a month. Leisure spending ${m(spent('leisure'))}; saved leisure plan ${m(S.budgets[S.month]?.leisure||0)}. Benefits are capped at 100.`,diner],mall:['A monthly payment is a full commitment',`The device instalment totals $600 over 24 months, versus $420 cash. A $5 arcade visit returns $0 cash. Scores and souvenirs are separate from your financial goal.`,contract],dealer:['Compare transport over time',`Transit ${m(E.profiles[S.profile].transport)}/month versus the supplied bike’s $350 upfront and $10/month. Cash affordability and practical access both matter.`,transport],lucky:['Odds and exposure',`Red or black wins on 18 of 37 outcomes; zero loses. Inclusive return is twice the stake on a win. Expected loss is 1/37 of total red/black stakes. Lifetime wagers ${m(S.casinoWagers)}, net ${m(S.casinoNet)}.`,lucky]};const c=content[id];modal(c[0],`<p>${esc(c[1])}</p>`,[{text:id==='gym'?(S.used.fountain===S.month?'Benefit already used':'Drink water'):'Explore the choice',disabled:id==='gym'&&S.used.fountain===S.month,fn:c[2]}],()=>location(id));}
 function lucky(){const c=S.casino,f=E.forecast(S);modal('Lucky’s · cash at risk',`<p>Playable fictional roulette and slots. Every wager is a real cash change. No stake on credit or automatic top-up. Ten wagers per visit; each new visit uses one time block.</p><p>Cash ${m(S.cash)}. Available before payday ${m(f.available)}. Lifetime staked ${m(S.casinoWagers)}; net ${m(S.casinoNet)}. Wins are possible; long-run odds favour the house.</p><label class=field>Session wager limit ($)<input id=casinoLimit type=number min=5 step=5 value=${c?.active?c.limit/100:20}></label><p>The limit measures total stakes, including re-wagered wins. Raising it exposes more essential money; you can leave at any time.</p>`,roomButtons('lucky',[{text:c?.active?'Return to the tables':'Start a casino visit',fn:()=>{const limit=amount('casinoLimit');if(!Number.isSafeInteger(limit)||limit<500){toast('Choose a limit of at least $5.');return;}if(c?.active){if(limit===c.limit)casinoTables();else reviseLimit(limit);}else if(commit(s=>E.casinoEnter(s,limit)))casinoTables();}},{text:'Review essential commitments',fn:calendar}]),close);}
 function reviseLimit(limit){const f=E.forecast(S);modal('Revise the wager limit',`<p>Old limit ${m(S.casino.limit)} → ${m(limit)}. Cash ${m(S.cash)}. Available before payday ${m(f.available)}. Remaining exposure ${m(Math.max(0,limit-S.casino.wagered))}. ${limit-S.casino.wagered>f.available?'This exposure can use money reserved for essentials or savings.':''}</p>`,[{text:'Set this limit',fn:()=>{if(limit<S.casino.wagered){toast('A limit cannot undo recorded wagers.');return;}if(commit(s=>{s.casino.limit=limit;return{ok:true};}))casinoTables();}}],lucky);}
 function casinoTables(){const c=S.casino;if(!c?.active){lucky();return;}modal('Casino tables · visible odds',`<canvas id=casinoArt class=activityCanvas width=640 height=200 aria-label='Illustrated casino cabinets'></canvas><p>Wagers ${c.plays}/10 · total stake ${m(c.wagered)}/${m(c.limit)} · cash ${m(S.cash)} · available ${m(E.forecast(S).available)}</p>${c.last?`<div class=document role=status>${c.last.kind==='slots'?esc(c.last.reels.join(' / ')):'Roulette: '+c.last.number} · stake ${m(c.last.stake)} · inclusive payout ${m(c.last.payout)} · cash change ${m(c.last.net)}</div>`:''}<h3>European roulette: 37 equally likely numbers</h3><label class=field>Stake<select id=rouletteStake><option value=500>$5</option><option value=2000>$20</option><option value=5000>$50</option></select></label><label class=field>Bet<select id=rouletteKind><option value=red>Red — 18/37, payout 2×</option><option value=black>Black — 18/37, payout 2×</option><option value=seven>Straight seven — 1/37, payout 36×</option></select></label><h3>Three-reel slots</h3><p>Independent reels each use a 13-symbol bag: cherries 4, lemon 3, bell 2, star 2, gem 1, seven 1. Triple seven pays 100×; other triples 10×; exactly one pair pays 0.6×; otherwise 0. Inclusive returns. Theoretical return ≈82.06%; expected loss ≈17.94% of stakes. No near-miss manipulation.</p><label class=field>Slot stake<select id=slotStake><option value=500>$5</option><option value=1000>$10</option><option value=2500>$25</option></select></label>`,[{text:'Place roulette wager',testid:'roulette-wager',fn:()=>{if(commit(s=>E.roulette(s,Number($('rouletteStake').value),$('rouletteKind').value)))casinoTables();}},{text:'Spin slots',fn:()=>{if(commit(s=>E.slots(s,Number($('slotStake').value))))casinoTables();}},{text:'Revise limit',fn:lucky},{text:'Leave casino',fn:()=>{if(commit(s=>{s.casino.active=false;return{ok:true};}))close();}}],lucky);const cx=$('casinoArt').getContext('2d');PPArt.sprite(cx,'roomsB','lucky',320,200,640,200);if(c.last?.kind==='slots'){cx.fillStyle='#234d39ed';cx.fillRect(142,24,356,150);c.last.reels.forEach((name,i)=>PPArt.sprite(cx,'luckySymbols',name,213+i*107,157,85,110));}else if(c.last){cx.fillStyle='#234d39ed';cx.fillRect(260,24,120,150);cx.fillStyle='#fff5de';cx.font='bold 64px Trebuchet MS';cx.textAlign='center';cx.fillText(String(c.last.number),320,124);}}
 function monthReview(){const missing=E.missing(S);if(S.day<30){modal('Month review','<p>The final payday is day 30. Advance the calendar to collect it and review the month.</p>',[{text:'Plan & calendar',fn:calendar}],close);return;}if(S.mode==='story'&&missing.length){objectives();toast('Complete the remaining choices before ending this chapter.');return;}const plan=S.budgets[S.month]||{},spent=cat=>S.ledger.filter(t=>t.month===S.month&&t.category===cat).reduce((n,t)=>n-(t.delta.cash||0),0),rows=['food','leisure','goal','emergency','debt'].map(k=>[k,m(plan[k]||0),m(spent(k)),m(spent(k)-(plan[k]||0))]);modal('Month '+S.month+' · review and revise',`<p>Cash ${m(S.cash)} · debt ${m(S.card+(S.loan?.balance||0))} · overdue bills ${m(S.unpaid.reduce((n,b)=>n+b.amount,0))}. Goal ${m(S.goal)}. ${S.food?.month===S.month?'Meal coverage paid.':'No complete meal plan: month-end energy −10 and stress +5, before regular recovery.'}</p>${table(rows,['Category','Planned','Actual cash use','Over / under'])}<p>Scheduled bills are separate. Transfers move your money between accounts; fees and investment gains are recorded when the month closes.</p><label class=field>What changed, and what will you do next?<textarea id=reviewReason maxlength=600 data-testid=month-reason placeholder='Use a figure from your plan or record to explain a revision.'></textarea></label><p id=reviewError class=error></p>`,[{text:S.mode==='story'&&S.month===6?'Complete the story':'Save review and start next month',testid:'month-next',fn:()=>{const why=$('reviewReason').value.trim();if(S.mode==='story'&&why.length<8){$('reviewError').textContent='Add a brief reflection using your plan or a consequence.';return;}if(commit(s=>{E.reason(s,'review','Month review',why);return E.advance(s);}))S.completed?finalReview():chapterIntro();}},{text:'Make a transfer or repayment first',fn:transfers}],calendar);}
 function finalReview(){const debt=S.card+(S.loan?.balance||0),unpaid=S.unpaid.reduce((n,b)=>n+b.amount,0),evidence=S.decisions.map(d=>[`M${d.month}`,d.key,d.choice,d.reason]);modal('Your financial journey',`<p>You managed six months as ${esc(E.profiles[S.profile].name.toLowerCase())}. Financial outcomes and evidence of learning are shown separately. A missed goal or an unlucky event does not erase a reasoned decision.</p>${table([['Goal',m(S.goal)+' / $1,200'],['Cash / emergency',m(S.cash)+' / '+m(S.emergency)],['Investment value',m(S.investment)],['Debt / overdue bills',m(debt)+' / '+m(unpaid)],['Remaining device instalments',m(S.contract?.kind==='term'?Math.max(0,24-(S.month-S.contract.start+1))*2500:0)],['Gambling outcome',m(S.casinoNet)+' net on '+m(S.casinoWagers)+' staked'],['Play time',Math.round(S.playedSeconds/60)+' minutes; design target 60–90'],['Learning evidence',S.decisions.length+' saved choices and monthly revisions']],['Measure','Outcome'])}<h3>Your reasons and revisions</h3>${table(evidence,['Month','Investigation','Choice','Reason'])}<p>Money outcomes depend on scenario, timing, choices, and chance. Evidence supports a teacher’s review; the game does not automatically grade CALM mastery.</p>`,[{text:'Download journey and evidence',fn:downloadReport},{text:'Start separate Free Play',fn:()=>newGame('free')},{text:'Return to title',fn:title}],null);}
 function reportText(){return `Paycheck Panic financial journey\nRules ${E.VERSION}\nScenario ${E.profiles[S.profile].name} · ${S.mode} · month ${S.month}, day ${S.day}\nCash ${m(S.cash)} · goal ${m(S.goal)} · emergency ${m(S.emergency)} · investments ${m(S.investment)}\nDebt ${m(S.card+(S.loan?.balance||0))} · overdue ${m(S.unpaid.reduce((n,b)=>n+b.amount,0))}\nCasino outcome ${m(S.casinoNet)} on stakes ${m(S.casinoWagers)}\n\nCHOICES AND REVISIONS\n`+S.decisions.map(d=>`Month ${d.month} day ${d.day} — ${d.key}: ${d.choice}\nReason: ${d.reason}`).join('\n\n')+'\n\nTRANSACTIONS\n'+S.ledger.map(t=>`M${t.month} D${t.day} ${t.label}: ${Object.entries(t.delta).map(([k,v])=>k+' '+m(v)).join(', ')}${t.due?' · due '+m(t.due):''}${t.unpaid?' · unpaid '+m(t.unpaid):''}`).join('\n');}
 function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function downloadReport(){download('Paycheck-Panic-financial-journey.txt',reportText(),'text/plain');}
 function downloadBackup(){download('Paycheck-Panic-campaign-backup.json',JSON.stringify({schema:3,rules:E.VERSION,revision,savedAt:new Date().toISOString(),state:S},null,2),'application/json');}
 function title(){save();paused=true;W.clear();A.suspend();close();$('title').hidden=false;$('hud').hidden=$('toolbar').hidden=$('objective').hidden=true;refreshContinue();measure();}
 function savedGames(){let list=[];try{list=JSON.parse(localStorage.getItem(indexKey)||'[]');}catch(e){}modal('Your independent campaigns',`<p>Story and Free Play have separate identities. Earlier campaigns remain available through Earlier version on the title screen.</p><ul class=taskList>${list.map(c=>`<li>${esc(E.profiles[c.profile]?.name||c.profile)} · ${esc(c.mode)} · month ${c.month}${c.completed?' · complete':''}<button data-load='${esc(c.id)}'>Continue</button></li>`).join('')||'<li>No new campaigns saved yet.</li>'}</ul><label class=field>Restore a downloaded v3 backup<input id=backupFile type=file accept='application/json,.json'></label><p id=backupError class=error></p>`,S?[{text:'Download current campaign backup',fn:downloadBackup}]:[],S?close:()=>{$('title').hidden=false;close();});$('modal').querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>load(b.dataset.load));$('backupFile').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>5000000)throw Error('Choose a campaign JSON smaller than 5 MB.');const envelope=JSON.parse(await file.text());if(!E.valid(envelope.state))throw Error('This is not a valid v3 campaign.');S=structuredClone(envelope.state);S.id=crypto.randomUUID();revision=0;if(save())start();}catch(err){$('backupError').textContent=err.message||'The backup was not restored.';}};}
 function refreshContinue(){let id;try{id=localStorage.getItem(selectedKey);}catch(e){}$('continue').hidden=!id;$('continue').onclick=()=>load(id);}
 function locations(){modal('Choose a walking route','<p>Choose a destination, then walk to its marked door and press E. A route does not advance the calendar.</p>',W.buildings.map(b=>({text:b.name,fn:()=>{close();W.navigate(b.id);}})),close);}
 function pause(){if(!S)return;paused=true;W.clear();A.suspend();save();modal('Paused','<p>The calendar and activity timer are stopped. Your costs, financial receipts, and activity progress are saved.</p>',[{text:'Resume',testid:'resume-game',fn:()=>{paused=false;A.active?A.resume():close();}},{text:'Download campaign backup',fn:downloadBackup},{text:'Return to title',fn:title}],null);}
 const api={state,save,commit,modal,toast,location,pause,paused:()=>paused,busy:()=>paused||!$('modalWrap').hidden||!$('title').hidden||A.active,playing:()=>!paused&&$('title').hidden,moved:()=>{if(S&&!E.marked(S,'move'))commit(s=>{E.mark(s,'move');return{ok:true};});},visit:()=>hud(),autoPause:()=>{if(S&&!paused&&$('title').hidden)pause();},escape:()=>{if(paused){paused=false;A.active?A.resume():close();}else if(A.active)pause();else if(!$('modalWrap').hidden){if(modalBack)modalBack();else close();}else pause();}};
 A.init(api);$('storyStart').onclick=()=>{$('title').hidden=true;newGame('story');};$('freeStart').onclick=()=>{$('title').hidden=true;newGame('free');};$('savedGames').onclick=()=>{$('title').hidden=true;savedGames();};$('titleHelp').onclick=()=>{$('title').hidden=true;help();};$('planButton').onclick=()=>A.active?pause():calendar();$('locationsButton').onclick=()=>A.active?pause():locations();$('helpButton').onclick=()=>A.active?pause():help();$('pauseButton').onclick=pause;$('receipt').onclick=()=>A.active?pause():ledger();$('objective').onclick=()=>A.active?pause():S.completed?finalReview():objectives();$('soundButton').onclick=()=>commit(s=>{s.settings.muted=!s.settings.muted;return{ok:true};});$('motionButton').onclick=()=>commit(s=>{s.settings.reduced=!s.settings.reduced;return{ok:true};});
 let audioContext;document.addEventListener('click',e=>{if(!S||S.settings.muted||!e.target.closest('button'))return;try{audioContext=audioContext||new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.connect(gain);gain.connect(audioContext.destination);osc.frequency.value=440;gain.gain.setValueAtTime(.035,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.045);osc.start();osc.stop(audioContext.currentTime+.05);}catch(e){}});
 document.addEventListener('keydown',e=>{if(e.key!=='Tab'||$('modalWrap').hidden)return;const els=[...$('modal').querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')].filter(el=>el.offsetParent!==null),first=els[0],last=els.at(-1);if(!first)return;if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('modal'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
 setInterval(()=>{if(S&&!paused&&$('title').hidden){save();hud();}},3000);addEventListener('pagehide',save);refreshContinue();measure();
 return api;
})();
